try:
    result = divide(10, 0)
except ZeroDivisionError:
    print("Tidak bisa bagi dengan nol")
except Exception as e:
    print(f"Error: {e}")
else:
    print(f"Hasil: {result}")
finally:
    print("Selesai")

Asynchronous programming memungkinkan kode berjalan tanpa menunggu operasi lain selesai. Contoh di JavaScript:

// Synchronous: nunggu satu per satu
console.log('1');
console.log('2');
console.log('3');

// Asynchronous: tidak blocking
console.log('1');
setTimeout(() => console.log('2'), 1000);  // delay 1 detik
console.log('3');
// Output: 1, 3, 2 (karena 2 delay)

// Dengan Promise
fetch('/api/users')
    .then(res => res.json())
    .then(data => console.log(data));

// Dengan async/await (lebih readable)
async function getUsers() {
    try {
        const res = await fetch('/api/users');
        const data = await res.json();
        return data;
    } catch (err) {
        console.error('Error:', err);
    }
}

.grid-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1rem;
    padding: 1rem;
}

.grid-item {
    background: #fff;
    padding: 1.5rem;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

/* Untuk mobile */
@media (max-width: 600px) {
    .grid-container {
        grid-template-columns: 1fr;
    }
}

/* Untuk tablet */
@media (min-width: 601px) and (max-width: 1024px) {
    .grid-container {
        grid-template-columns: repeat(2, 1fr);
    }
}
